evaluateBeanshell.condition:
String mods = "${project.parent.modules}";
String deps = "${project.dependencies}";
// Scope to this project's OWN group: <dependencies> also carries inherited and
// managed third-party entries (jspecify, lombok, ...), which are not reactor
// modules and must not be reported as stale.
String grp = "${project.groupId}";

// Every reactor module except this aggregator itself, by its last path segment.
java.util.List expected = new java.util.ArrayList();
String inner = mods.substring(1, mods.length() - 1);
String[] parts = inner.split(",");
for (int i = 0; i < parts.length; i++) {
    String mod = parts[i].trim();
    if (mod.length() == 0) continue;
    String art = mod.substring(mod.lastIndexOf('/') + 1);
    if (art.equals("coverage")) continue;
    expected.add(art);
}

java.util.List missing = new java.util.ArrayList();
for (int i = 0; i < expected.size(); i++) {
    String art = (String) expected.get(i);
    if (deps.indexOf("groupId=" + grp + ", artifactId=" + art + ",") < 0) {
        missing.add(art);
    }
}

java.util.List stale = new java.util.ArrayList();
String[] dparts = deps.split("Dependency \\{");
for (int i = 0; i < dparts.length; i++) {
    String d = dparts[i];
    String probe = "groupId=" + grp + ", artifactId=";
    int g = d.indexOf(probe);
    if (g < 0) continue;
    String rest = d.substring(g + probe.length());
    int comma = rest.indexOf(',');
    if (comma < 0) continue;
    String art = rest.substring(0, comma);
    if (!expected.contains(art)) stale.add(art);
}

if (!missing.isEmpty()) {
    print("  MISSING from coverage/pom.xml <dependencies>: " + missing);
    print("  -> these modules build, but contribute NO coverage to the aggregate or to Sonar.");
}
if (!stale.isEmpty()) {
    print("  STALE in coverage/pom.xml <dependencies>: " + stale);
    print("  -> no matching entry in the parent's <modules>.");
}
missing.isEmpty() && stale.isEmpty();
